package glitch

import data.glitch_lib

check_credential_key(key) {
    regex.match("(?i)(password|secret|key|token|credential|auth|apiKey|secretKey|accessToken|passphrase|privateKey|secretValue)", key)
}

find_hardcoded_credentials(key, value, path) = findings {
    check_credential_key(key)
    value.ir_type == "String"
    findings := {{
        "type": "sec_hard_secr",
        "element": value,
        "path": path,
        "description": "Hard-coded credential detected in IaC script. (CWE-798)"
    }}
} else {
    value.ir_type == "Hash"
    findings := {f |
        pair := value.value[_]
        nested_key := pair.key.value
        nested_value := pair.value
        f := find_hardcoded_credentials(nested_key, nested_value, path)[_]
    }
} else {
    value.ir_type == "Array"
    findings := {f |
        element := value.value[_]
        f := traverse_value(element, path)[_]
    }
} else {
    findings := set()
}

traverse_value(value, path) = findings {
    value.ir_type == "Hash"
    findings := {f |
        pair := value.value[_]
        nested_key := pair.key.value
        nested_value := pair.value
        f := find_hardcoded_credentials(nested_key, nested_value, path)[_]
    }
} else {
    value.ir_type == "Array"
    findings := {f |
        element := value.value[_]
        f := traverse_value(element, path)[_]
    }
} else {
    findings := set()
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variable := parent.variables[_]
    findings := find_hardcoded_credentials(variable.name, variable.value, parent.path)
    result := findings[_]
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    findings := find_hardcoded_credentials(attr.name, attr.value, parent.path)
    result := findings[_]
}

